# Construct output by periodic motifs in the three zero rectangles.
g = [[8]*22 for _ in range(26)]
# rectangles and motifs
motifs = [
    (2,3,9,6, [[0,1,0],[1,0,1],[1,1,0]]),
    (4,13,8,6, [[4,0,0],[4,4,0]]),
    (16,3,6,8, [[3,0,3,3],[0,3,0,3],[3,3,0,3]])
]
for r0,c0,h,w,m in motifs:
    for r in range(h):
        for c in range(w):
            g[r0+r][c0+c] = m[r%len(m)][c%len(m[0])]
print('\n'.join(' '.join(map(str,row)) for row in g))
